function CopyButton({ text }) {
  const [copied, setCopied] = useState(false)
  return (
    <button
      onClick={() => { navigator.clipboard.writeText(text); setCopied(true); setTimeout(() => setCopied(false), 1500) }}
      className="press-btn"
      style={{ position:'absolute', top:8, right:8, background:'#252525', border:'1px solid #333',
        borderRadius:4, color: copied ? '#34c759' : '#666', padding:'3px 8px', fontSize:11,
        cursor:'pointer', fontFamily:'var(--font-mono)',
        transform: copied ? 'scale(1.08)' : 'scale(1)',
        borderColor: copied ? '#34c75966' : '#333' }}>
      {copied ? '✓' : 'copy'}
    </button>
  )
}

function CountUp({ value, duration = 900 }) {
  const [display, setDisplay] = useState(0)
  const prevValue = useRef(0)

  useEffect(() => {
    const from = prevValue.current
    const to = value
    if (from === to) return
    const start = performance.now()
    let raf
    const tick = (now) => {
      const elapsed = now - start
      const t = Math.min(1, elapsed / duration)
      // ease-out cubic
      const eased = 1 - Math.pow(1 - t, 3)
      setDisplay(Math.round(from + (to - from) * eased))
      if (t < 1) raf = requestAnimationFrame(tick)
      else prevValue.current = to
    }
    raf = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(raf)
  }, [value, duration])

  return <>{display.toLocaleString()}</>
}

function CodeBlock({ code }) {
  return (
    <div style={{ position:'relative', background:'#111', border:'1px solid #252525',
      borderRadius:6, padding:'12px 52px 12px 14px', margin:'8px 0' }}>
      <pre style={{ margin:0, fontSize:13, color:'#c8192e', fontFamily:'var(--font-mono)',
        overflowX:'auto', whiteSpace:'pre-wrap', wordBreak:'break-all' }}>
        <span style={{ color:'#444' }}>$ </span>{code}
      </pre>
      <CopyButton text={code} />
    </div>
  )
}

// ── Seasonal site events ──────────────────────────────────────────────
// HyperNix's "birthday" is April 20, 2026 — the counter turns 1 on April
// 20, 2027, 2 the year after, and so on. Everything else here is a plain
// date-match (or date-range, for Pride Month) against the visitor's local
// clock. April Fools' is handled separately (see AprilFoolsPage) since it
// replaces the whole site for a minute instead of just showing a banner.
const HYPERNIX_BIRTH_YEAR = 2026
const BANNER_HEIGHT = 40

// nth weekday of a given month, e.g. nthWeekdayOfMonth(2026, 10, 4, 4) is
// the 4th Thursday of November 2026 (US Thanksgiving). weekday: 0=Sun..6=Sat.
function nthWeekdayOfMonth(year, monthIndex0, weekday, n) {
  const d = new Date(year, monthIndex0, 1)
  let count = 0
  while (d.getMonth() === monthIndex0) {
    if (d.getDay() === weekday) {
      count += 1
      if (count === n) return d.getDate()
    }
    d.setDate(d.getDate() + 1)
  }
  return null
}

// Last occurrence of a given weekday in a month, e.g. Memorial Day (last
// Monday of May). weekday: 0=Sun..6=Sat.
function lastWeekdayOfMonth(year, monthIndex0, weekday) {
  const d = new Date(year, monthIndex0 + 1, 0) // last calendar day of the month
  while (d.getDay() !== weekday) {
    d.setDate(d.getDate() - 1)
  }
  return d.getDate()
}

function getActiveSiteEvent(now = new Date()) {
  const month = now.getMonth() + 1
  const day = now.getDate()
  const year = now.getFullYear()

  if (month === 4 && day === 20 && year > HYPERNIX_BIRTH_YEAR) {
    return { id: `birthday-${year}`, kind: 'birthday', age: year - HYPERNIX_BIRTH_YEAR }
  }
  if (month === 12 && day === 25) {
    return { id: `christmas-${year}`, kind: 'christmas' }
  }
  if (month === 12 && day === 24) {
    return { id: `christmas-eve-${year}`, kind: 'christmas-eve' }
  }
  if (month === 12 && day === 31) {
    return { id: `newyearseve-${year}`, kind: 'newyearseve' }
  }
  if (month === 1 && day === 1) {
    return { id: `newyear-${year}`, kind: 'newyear' }
  }
  if (month === 1 && day === nthWeekdayOfMonth(year, 0, 1, 3)) {
    return { id: `mlk-${year}`, kind: 'mlk' }
  }
  if (month === 2 && day === 14) {
    return { id: `valentines-${year}`, kind: 'valentines' }
  }
  if (month === 3 && day === 8) {
    return { id: `iwd-${year}`, kind: 'iwd' }
  }
  if (month === 3 && day === 17) {
    return { id: `stpatricks-${year}`, kind: 'stpatricks' }
  }
  if (month === 3 && day === 31) {
    return { id: `tdov-${year}`, kind: 'tdov' }
  }
  if (month === 4 && day === 22) {
    return { id: `earthday-${year}`, kind: 'earthday' }
  }
  if (month === 5 && day === 5) {
    return { id: `cincodemayo-${year}`, kind: 'cincodemayo' }
  }
  if (month === 5 && day === lastWeekdayOfMonth(year, 4, 1)) {
    return { id: `memorialday-${year}`, kind: 'memorialday' }
  }
  if (month === 6 && day === 19) {
    return { id: `juneteenth-${year}`, kind: 'juneteenth' }
  }
  if (month === 10 && day === 31) {
    return { id: `halloween-${year}`, kind: 'halloween' }
  }
  if (month === 11 && day === nthWeekdayOfMonth(year, 10, 4, 4)) {
    return { id: `thanksgiving-${year}`, kind: 'thanksgiving' }
  }
  if (month === 11 && day === 20) {
    return { id: `tdor-${year}`, kind: 'tdor' }
  }
  if (month === 7 && (day === 3 || day === 4)) {
    return { id: `july4-${year}`, kind: 'july4', eve: day === 3 }
  }
  if (month === 9 && day === nthWeekdayOfMonth(year, 8, 1, 1)) {
    return { id: `laborday-${year}`, kind: 'laborday' }
  }
  if (month === 9 && day === 23) {
    return { id: `bivisibility-${year}`, kind: 'bivisibility' }
  }
  if (month === 10 && day === 11) {
    return { id: `comingout-${year}`, kind: 'comingout' }
  }
  if (month === 6) {
    return { id: `pride-${year}`, kind: 'pride' }
  }
  return null
}

function PrideFlagIcon({ size = 18 }) {
  const stripes = ['#e40303', '#ff8c00', '#ffed00', '#008026', '#004dff', '#750787']
  // Nested hoist-side chevron, largest (black) to smallest (white), drawn
  // back-to-front so each color shows as a band around the next.
  const chevrons = [
    { tip: 18,   fill: '#000000' },
    { tip: 15.6, fill: '#7a4a20' },
    { tip: 13.2, fill: '#5bcefa' },
    { tip: 10.8, fill: '#f5a9b8' },
    { tip: 8.4,  fill: '#ffffff' },
  ]
  const h = size * 0.66
  return (
    <svg width={size} height={h} viewBox="0 0 30 20" style={{ borderRadius: 2, flexShrink: 0 }}>
      {stripes.map((c, i) => (
        <rect key={c} x="0" y={i * (20 / 6)} width="30" height={20 / 6 + 0.6} fill={c} />
      ))}
      {chevrons.map((ch) => (
        <polygon key={ch.fill} points={`0,0 ${ch.tip},10 0,20`} fill={ch.fill} />
      ))}
    </svg>
  )
}

function AmericanFlagIcon({ size = 18 }) {
  const h = size * 0.66
  const stripeH = h / 7
  const stars = [[2,2],[5,2],[8,2],[2,5],[5,5],[8,5],[2,8],[5,8]]
  return (
    <svg width={size} height={h} viewBox="0 0 30 20" style={{ borderRadius: 2, flexShrink: 0 }}>
      {[...Array(7)].map((_, i) => (
        <rect key={i} x="0" y={i * stripeH} width="30" height={stripeH + 0.4} fill={i % 2 === 0 ? '#b31942' : '#ffffff'} />
      ))}
      <rect x="0" y="0" width="13" height={stripeH * 4} fill="#0a3161" />
      {stars.map(([x, y], idx) => (
        <circle key={idx} cx={x + 1} cy={y + 1} r="0.6" fill="#ffffff" />
      ))}
    </svg>
  )
}

